import { useState, useEffect } from 'react';
import { useNavigate, useSearchParams, Link } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { useModal } from '../../contexts/ModalContext';
import ThemeToggle from '../ui/ThemeToggle';
import NexusLogo from '../ui/NexusLogo';
import api from '../../services/api';
import { PASSWORD_POLICY_MESSAGE, validatePassword } from '../../utils/password';

function Login() {
  const [currentStep, setCurrentStep] = useState('login'); // 'login', 'register', 'forgot'
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { isAuthenticated } = useAuth();

  useEffect(() => {
    if (isAuthenticated) navigate('/dashboard');
  }, [isAuthenticated, navigate]);

  // Se vir de /register, muda pra step de registro
  useEffect(() => {
    if (searchParams.get('register') === 'true') {
      setCurrentStep('register');
    }
  }, [searchParams]);

  return (
    <div className="auth-page">
      {/* Return to landing page */}
      <Link to="/" className="auth-back-link" aria-label="Voltar para a página inicial">
        <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
        </svg>
        <span>Início</span>
      </Link>

      {/* Floating Modern Theme Toggle */}
      <div className="auth-theme-toggle-wrap">
        <ThemeToggle variant="pill" id="login-theme-toggle" />
      </div>

      <div className="auth-circle-container">
        {/* Animated 3D Flip Container */}
        <div
          className="auth-flip-wrapper"
          style={{
            transformStyle: 'preserve-3d',
            transform:
              currentStep === 'login'
                ? 'rotateY(0deg)'
                : currentStep === 'register'
                ? 'rotateY(120deg)'
                : 'rotateY(-120deg)',
          }}
        >
          {/* Face 1: Login */}
          <div
            className="auth-flip-face"
            style={{
              pointerEvents: currentStep === 'login' ? 'auto' : 'none',
            }}
          >
            <LoginForm onNavigate={setCurrentStep} />
          </div>

          {/* Face 2: Forgot Password */}
          <div
            className="auth-flip-face"
            style={{
              transform: 'rotateY(120deg)',
              pointerEvents: currentStep === 'forgot' ? 'auto' : 'none',
            }}
          >
            <ForgotForm onNavigate={setCurrentStep} />
          </div>

          {/* Face 3: Register */}
          <div
            className="auth-flip-face"
            style={{
              transform: 'rotateY(-120deg)',
              pointerEvents: currentStep === 'register' ? 'auto' : 'none',
            }}
          >
            <RegisterForm onNavigate={setCurrentStep} />
          </div>
        </div>
      </div>
    </div>
  );
}

function LoginForm({ onNavigate }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState([]);
  const { login } = useAuth();
  const { alert } = useModal();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setErrors([]);

    const newErrors = [];
    if (!email) {
      newErrors.push('Email é obrigatório');
    } else if (!email.includes('@') || !email.includes('.')) {
      newErrors.push('Email inválido');
    }

    if (!password) {
      newErrors.push('Senha é obrigatória');
    } else if (password.length < 6) {
      newErrors.push('Senha deve ter no mínimo 6 caracteres');
    }

    if (newErrors.length > 0) {
      setErrors(newErrors);
      return;
    }

    setLoading(true);

    try {
      await login(email.trim().toLowerCase(), password);
      navigate('/dashboard');
    } catch (err) {
      alert({
        title: 'Acesso Negado',
        message: err.response?.data?.message || 'E-mail ou senha incorretos. Verifique suas credenciais e tente novamente.',
        variant: 'danger'
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fp-content">
      <div className="auth-logo">
        <NexusLogo className="w-6 h-6" />
      </div>

      <div className="auth-form-header">
        <h1 className="auth-form-title">Nexus Control</h1>
        <span className="auth-form-tag">ENTERPRISE ACCESS</span>
        <p className="auth-form-subtitle">Acesso corporativo seguro à plataforma</p>
      </div>

      <form onSubmit={handleSubmit} noValidate className="fp-form">
        {errors.map((err, idx) => (
          <p key={idx} className="auth-field-error" role="alert">{err}</p>
        ))}

        <div className="auth-field">
          <div className="auth-input-wrap">
            <span className="auth-input-icon">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                <rect x="2" y="4" width="20" height="16" rx="2" />
                <path d="M2 7l10 7 10-7" />
              </svg>
            </span>
            <input
              id="email"
              name="email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="auth-input"
              placeholder="seu@email.com"
              aria-label="Email"
              autoComplete="email"
              maxLength={254}
              spellCheck="false"
              required
              disabled={loading}
            />
          </div>
        </div>

        <div className="auth-field">
          <div className="auth-input-wrap">
            <span className="auth-input-icon">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                <rect x="5" y="11" width="14" height="10" rx="2" />
                <path d="M8 11V7a4 4 0 0 1 8 0v4" />
              </svg>
            </span>
            <input
              id="senha"
              name="senha"
              type={showPassword ? 'text' : 'password'}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="auth-input auth-input--padded"
              placeholder="••••••••"
              aria-label="Senha"
              autoComplete="current-password"
              maxLength={128}
              required
              disabled={loading}
            />
            <button
              type="button"
              className="auth-eye-btn"
              onClick={() => setShowPassword(!showPassword)}
              aria-label={showPassword ? 'Ocultar senha' : 'Mostrar senha'}
            >
              <EyeIcon visible={showPassword} />
            </button>
          </div>
        </div>

        <button type="submit" className="auth-submit-btn" disabled={loading}>
          {loading ? 'Entrando...' : 'ENTRAR NA CONTA'}
        </button>
      </form>

      <button
        type="button"
        onClick={() => onNavigate('register')}
        className="auth-link-btn"
        aria-label="Ir para cadastro"
        style={{ marginTop: '10px' }}
      >
        Não tem uma conta? <strong>Criar conta</strong>
      </button>

      <button
        type="button"
        onClick={() => onNavigate('forgot')}
        className="auth-link-btn"
        style={{ marginTop: '4px' }}
      >
        Esqueceu sua <strong>senha?</strong>
      </button>
    </div>
  );
}

function RegisterForm({ onNavigate }) {
  const [formData, setFormData] = useState({ nome: '', email: '', senha: '', confirm: '', senha_conta_desativada: '' });
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [showRecoveryPassword, setShowRecoveryPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [needsRecoveryVerification, setNeedsRecoveryVerification] = useState(false);
  const [recoveredHistory, setRecoveredHistory] = useState(false);
  const { register } = useAuth();
  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (formData.senha !== formData.confirm) {
      setError('As senhas não coincidem');
      return;
    }

    const passwordError = validatePassword(formData.senha);
    if (passwordError) {
      setError(passwordError);
      return;
    }

    setLoading(true);

    try {
      const payload = {
        nome: formData.nome.trim(),
        email: formData.email.trim().toLowerCase(),
        senha: formData.senha,
      };
      if (needsRecoveryVerification && formData.senha_conta_desativada) {
        payload.senha_conta_desativada = formData.senha_conta_desativada;
      }
      const result = await register(payload);
      if (result?.recuperou_historico) {
        setRecoveredHistory(true);
        setError('');
      }
      navigate('/dashboard');
    } catch (err) {
      const validationErrors = err.response?.data?.errors;
      const verificacaoDesativada = validationErrors?.verificacao_conta_desativada === true;
      if (verificacaoDesativada) {
        setNeedsRecoveryVerification(true);
      }
      const validationMessage = Array.isArray(validationErrors)
        ? validationErrors.map(({ msg }) => msg).filter(Boolean).join('. ')
        : '';
      setError(
        validationMessage
        || err.response?.data?.message
        || err.message
        || (verificacaoDesativada
            ? 'Encontramos uma conta desativada com este e-mail. Confirme a senha da conta anterior para recuperar seu histórico.'
            : 'Erro ao criar conta'),
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fp-content">
      <div className="auth-logo">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" style={{ color: '#D4AF37' }}>
          <path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
          <circle cx="12" cy="7" r="4" />
        </svg>
      </div>

      <div className="auth-form-header">
        <h1 className="auth-form-title">Criar Conta</h1>
        <span className="auth-form-tag">NOVO USUÁRIO</span>
        <p className="auth-form-subtitle">Cadastre-se e comece a gerenciar seus itens</p>
      </div>

      <form onSubmit={handleSubmit} noValidate className="fp-form">
        {error && <p className="auth-field-error" role="alert">{error}</p>}
        {recoveredHistory && (
          <p className="auth-field-error" role="status" style={{ color: '#D4AF37' }}>
            Sua conta anterior foi recuperada com sucesso. Seu histórico voltou a contar.
          </p>
        )}

        <div className="auth-field">
          <div className="auth-input-wrap">
            <span className="auth-input-icon">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
                <circle cx="12" cy="7" r="4" />
              </svg>
            </span>
            <input
              id="register-nome"
              type="text"
              name="nome"
              value={formData.nome}
              onChange={handleChange}
              className="auth-input"
              placeholder="Nome completo"
              aria-label="Nome completo"
              maxLength={100}
              required
              disabled={loading}
            />
          </div>
        </div>

        <div className="auth-field">
          <div className="auth-input-wrap">
            <span className="auth-input-icon">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                <rect x="2" y="4" width="20" height="16" rx="2" />
                <path d="M2 7l10 7 10-7" />
              </svg>
            </span>
            <input
              id="register-email"
              type="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              className="auth-input"
              placeholder="seu@email.com"
              aria-label="Email de cadastro"
              autoComplete="email"
              maxLength={254}
              spellCheck="false"
              required
              disabled={loading}
            />
          </div>
        </div>

        <div className="auth-field">
          <div className="auth-input-wrap">
            <span className="auth-input-icon">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                <rect x="5" y="11" width="14" height="10" rx="2" />
                <path d="M8 11V7a4 4 0 0 1 8 0v4" />
              </svg>
            </span>
            <input
              id="register-senha"
              type={showPassword ? 'text' : 'password'}
              name="senha"
              value={formData.senha}
              onChange={handleChange}
              className="auth-input auth-input--padded"
              placeholder="Senha"
              aria-label="Senha de cadastro"
              autoComplete="new-password"
              maxLength={7}
              required
              disabled={loading}
            />
            <button
              type="button"
              className="auth-eye-btn"
              onClick={() => setShowPassword(!showPassword)}
              aria-label={showPassword ? 'Ocultar senha' : 'Mostrar senha'}
            >
              <EyeIcon visible={showPassword} />
            </button>
          </div>
          <p className="auth-password-hint">{PASSWORD_POLICY_MESSAGE}</p>
        </div>

        <div className="auth-field">
          <div className="auth-input-wrap">
            <span className="auth-input-icon">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                <rect x="5" y="11" width="14" height="10" rx="2" />
                <path d="M8 11V7a4 4 0 0 1 8 0v4" />
                <path d="M9 16l2 2 4-4" />
              </svg>
            </span>
            <input
              id="register-confirm"
              type={showConfirmPassword ? 'text' : 'password'}
              name="confirm"
              value={formData.confirm}
              onChange={handleChange}
              className="auth-input auth-input--padded"
              placeholder="Confirmar senha"
              aria-label="Confirmar senha"
              autoComplete="new-password"
              maxLength={7}
              required
              disabled={loading}
            />
            <button
              type="button"
              className="auth-eye-btn"
              onClick={() => setShowConfirmPassword(!showConfirmPassword)}
              aria-label={showConfirmPassword ? 'Ocultar confirmação de senha' : 'Mostrar confirmação de senha'}
            >
              <EyeIcon visible={showConfirmPassword} />
            </button>
          </div>
        </div>

        {needsRecoveryVerification && (
          <div className="auth-field">
            <div
              className="mb-2 rounded-lg px-3 py-2 text-[11px] leading-relaxed"
              style={{ background: 'rgba(212,175,55,0.08)', border: '1px solid rgba(212,175,55,0.35)', color: '#e2c97a' }}
              role="status"
            >
              Encontramos uma conta desativada com este e-mail. Confirme a senha da conta anterior para
              recuperar o histórico. Prefere começar do zero? Cadastre-se com outro e-mail.
            </div>
            <div className="auth-input-wrap">
              <span className="auth-input-icon">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M4 7h16M4 12h10M4 17h16" />
                  <circle cx="18" cy="12" r="2.5" />
                </svg>
              </span>
              <input
                id="register-senha-antiga"
                type={showRecoveryPassword ? 'text' : 'password'}
                name="senha_conta_desativada"
                value={formData.senha_conta_desativada}
                onChange={handleChange}
                className="auth-input auth-input--padded"
                placeholder="Senha da conta anterior"
                aria-label="Senha da conta anterior"
                autoComplete="current-password"
                maxLength={7}
                required
                disabled={loading}
              />
              <button
                type="button"
                className="auth-eye-btn"
                onClick={() => setShowRecoveryPassword(!showRecoveryPassword)}
                aria-label={showRecoveryPassword ? 'Ocultar senha anterior' : 'Mostrar senha anterior'}
              >
                <EyeIcon visible={showRecoveryPassword} />
              </button>
            </div>
          </div>
        )}

        <button type="submit" className="auth-submit-btn" disabled={loading} aria-label="Cadastrar">
          {loading ? 'Criando conta...' : 'CRIAR MINHA CONTA'}
        </button>
      </form>

      <button
        type="button"
        onClick={() => onNavigate('login')}
        className="auth-link-btn"
        aria-label="Ir para login"
        style={{ marginTop: '10px' }}
      >
        Já tem conta? <strong>Fazer login</strong>
      </button>
    </div>
  );
}

function ForgotForm({ onNavigate }) {
  const [step, setStep] = useState('request'); // 'request', 'reset', 'success'
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');
  const [confirmacao, setConfirmacao] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [resetToken, setResetToken] = useState('');

  const requestReset = async (event) => {
    event.preventDefault();
    setError('');
    setMessage('');
    setLoading(true);
    try {
      const response = await api.post('/auth/forgot-password', { email: email.trim().toLowerCase() });
      const token = response.data.data?.resetToken;
      
      if (token) {
        setResetToken(token);
        setMessage('Token de recuperação gerado! (Em produção, seria enviado por email)');
        setStep('reset');
      } else {
        setMessage('Se este email estiver cadastrado, as instruções de recuperação foram enviadas.');
        setStep('success');
      }
    } catch (requestError) {
      setError(requestError.response?.data?.message || 'Não foi possível iniciar a recuperação agora.');
    } finally {
      setLoading(false);
    }
  };

  const resetPassword = async (event) => {
    event.preventDefault();
    if (senha !== confirmacao) { 
      setError('As senhas não conferem');
      return;
    }
    const passwordError = validatePassword(senha);
    if (passwordError) {
      setError(passwordError);
      return;
    }
    setError('');
    setLoading(true);
    try {
      await api.post('/auth/reset-password', { token: resetToken, senha });
      setMessage('Senha redefinida com sucesso. Agora você já pode acessar o Nexus Control.');
      setStep('success');
    } catch (resetError) {
      setError(resetError.response?.data?.message || 'Não foi possível redefinir a senha.');
    } finally {
      setLoading(false);
    }
  };

  const icons = {
    request: (
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="8" cy="15" r="3.5" />
        <path d="m10.5 12.5 8-8M15 7l2 2m-5 1 2 2" />
      </svg>
    ),
    reset: (
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
        <rect x="5" y="11" width="14" height="10" rx="2" />
        <path d="M8 11V7a4 4 0 0 1 8 0v4" />
        <circle cx="12" cy="16" r="1.2" fill="currentColor" stroke="none" />
      </svg>
    ),
    success: (
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="12" cy="12" r="9" />
        <path d="M8 12l3 3 5-5" />
      </svg>
    ),
  };

  const titles = { request: 'Recuperar Senha', reset: 'Nova Senha', success: 'Senha Recuperada' };
  const subtitles = {
    request: 'Informe seu email para recuperar o acesso à sua conta.',
    reset: resetToken ? 'Use o token gerado para redefinir sua senha.' : 'Defina uma nova senha segura para sua conta.',
    success: message,
  };

  return (
    <div className="fp-content">
      <div className="auth-logo" style={{ color: '#D4AF37' }}>
        {icons[step]}
      </div>

      <div className="auth-form-header">
        <h1 className="auth-form-title">{titles[step]}</h1>
        <span className="auth-form-tag">RECUPERAÇÃO</span>
        <p className="auth-form-subtitle">{subtitles[step]}</p>
      </div>

      {step === 'request' && (
        <form onSubmit={requestReset} noValidate className="fp-form">
          <div className="auth-field">
            <div className="auth-input-wrap">
              <span className="auth-input-icon">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                  <rect x="2" y="4" width="20" height="16" rx="2" />
                  <path d="M2 7l10 7 10-7" />
                </svg>
              </span>
              <input
                id="recovery-email"
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="auth-input"
                placeholder="seu@email.com"
                autoComplete="email"
                required
                disabled={loading}
              />
            </div>
          </div>
          {message && <p className="auth-field-error" style={{ color: '#D4AF37' }} role="status">{message}</p>}
          {error && <p className="auth-field-error" role="alert">{error}</p>}
          <button type="submit" className="auth-submit-btn" disabled={loading} style={{ marginTop: '12px' }}>
            {loading ? 'Preparando...' : 'CONTINUAR'}
          </button>
        </form>
      )}

      {step === 'reset' && (
        <>
          {resetToken && (
            <div style={{ textAlign: 'left', marginBottom: '16px' }}>
              <p style={{ fontSize: '12px', color: '#94a3b8', marginBottom: '8px' }}>Token de recuperação (desenvolvimento):</p>
              <div style={{ 
                background: 'rgba(18, 18, 18, 0.8)', 
                border: '1px solid rgba(212, 175, 55, 0.3)', 
                borderRadius: '8px', 
                padding: '12px', 
                fontFamily: 'monospace', 
                fontSize: '11px', 
                color: '#D4AF37',
                wordBreak: 'break-all',
                marginBottom: '12px'
              }}>
                {resetToken}
              </div>
            </div>
          )}
          <form onSubmit={resetPassword} noValidate className="fp-form">
            <div className="auth-field">
              <div className="auth-input-wrap">
                <span className="auth-input-icon">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                    <rect x="5" y="11" width="14" height="10" rx="2" />
                    <path d="M8 11V7a4 4 0 0 1 8 0v4" />
                  </svg>
                </span>
                <input
                  id="recovery-password"
                  type={showPassword ? 'text' : 'password'}
                  value={senha}
                  onChange={(e) => setSenha(e.target.value)}
                  className="auth-input auth-input--padded"
                  placeholder="Nova senha"
                  autoComplete="new-password"
                  maxLength={7}
                  required
                />
                <button type="button" className="auth-eye-btn" onClick={() => setShowPassword(p => !p)} aria-label={showPassword ? 'Ocultar senha' : 'Mostrar senha'}>
                  <EyeIcon visible={showPassword} />
                </button>
              </div>
            </div>
            <div className="auth-field">
              <div className="auth-input-wrap">
                <span className="auth-input-icon">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                    <rect x="5" y="11" width="14" height="10" rx="2" />
                    <path d="M8 11V7a4 4 0 0 1 8 0v4" />
                    <path d="M9 16l2 2 4-4" />
                  </svg>
                </span>
                <input
                  id="recovery-confirmation"
                  type={showConfirmation ? 'text' : 'password'}
                  value={confirmacao}
                  onChange={(e) => setConfirmacao(e.target.value)}
                  className="auth-input auth-input--padded"
                  placeholder="Confirmar nova senha"
                  autoComplete="new-password"
                  maxLength={7}
                  required
                />
                <button type="button" className="auth-eye-btn" onClick={() => setShowConfirmation(p => !p)} aria-label={showConfirmation ? 'Ocultar senha' : 'Mostrar senha'}>
                  <EyeIcon visible={showConfirmation} />
                </button>
              </div>
              <p className="auth-password-hint">{PASSWORD_POLICY_MESSAGE}</p>
            </div>
            {error && <p className="auth-field-error" role="alert">{error}</p>}
            <button type="submit" className="auth-submit-btn" disabled={loading} style={{ marginTop: '12px' }}>
              {loading ? 'Redefinindo...' : 'REDEFINIR SENHA'}
            </button>
          </form>
        </>
      )}

      {step === 'success' && (
        <button type="button" className="auth-submit-btn" style={{ width: '80%', marginTop: '16px' }} onClick={() => onNavigate('login')}>
          VOLTAR PARA O LOGIN
        </button>
      )}

      {step !== 'success' && (
        <button
          type="button"
          onClick={() => onNavigate('login')}
          className="auth-link-btn"
          style={{ marginTop: '12px' }}
        >
          Voltar para o login
        </button>
      )}
    </div>
  );
}

function EyeIcon({ visible }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      {visible ? (
        <>
          <path d="M3 3l18 18M10.6 10.6a2 2 0 0 0 2.8 2.8M9.9 5.2A10.8 10.8 0 0 1 12 5c5.2 0 8.7 4.4 9.8 7a15.6 15.6 0 0 1-3.1 4.4M6.2 6.2C4.4 7.5 3.2 9.3 2.2 12c1.1 2.6 4.6 7 9.8 7 1 0 2-.2 2.9-.5" />
        </>
      ) : (
        <path d="M2.2 12C3.3 9.4 6.8 5 12 5s8.7 4.4 9.8 7c-1.1 2.6-4.6 7-9.8 7s-8.7-4.4-9.8-7Z M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z" />
      )}
    </svg>
  );
}

export default Login;
